-- ============================================================================
-- Visitor Management System — PROPOSED MIGRATION (NOT APPLIED)
-- Target: Neon PostgreSQL.  Purely additive: only CREATE TABLE / INDEX
-- IF NOT EXISTS. No DROP, no ALTER, no RENAME, no touching existing tables
-- (incl. visitor_sessions, live_chats, live_chat_messages).
-- Runs in one transaction: all-or-nothing.
-- Conventions: TEXT ids generated by the app (cuid), TIMESTAMPTZ for new
-- tables (existing tables use BIGINT epoch-ms; no FK to them anywhere).
-- ============================================================================
BEGIN;

-- 1. Access requests (public form submissions) -------------------------------
CREATE TABLE IF NOT EXISTS visitor_access_requests (
  id               TEXT PRIMARY KEY,
  full_name        TEXT NOT NULL,
  email            TEXT NOT NULL,
  mobile           TEXT NOT NULL,
  company          TEXT NOT NULL,
  designation      TEXT NOT NULL,
  purpose          TEXT NOT NULL,
  linkedin_url     TEXT,
  website_url      TEXT,
  status           TEXT NOT NULL DEFAULT 'pending'
                   CHECK (status IN ('pending','approved','rejected')),
  reviewed_at      TIMESTAMPTZ,
  reviewed_by      TEXT,
  reject_reason    TEXT,
  ip_address       TEXT,
  ip_anonymized_at TIMESTAMPTZ,
  user_agent       TEXT,
  created_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at       TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_var_status_created ON visitor_access_requests (status, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_var_email          ON visitor_access_requests (lower(email));
-- at most one open request per email (stops form spam / duplicates)
CREATE UNIQUE INDEX IF NOT EXISTS uq_var_pending_email
  ON visitor_access_requests (lower(email)) WHERE status = 'pending';

-- 2. Visitor accounts (created only after admin approval) --------------------
CREATE TABLE IF NOT EXISTS visitors (
  id                   TEXT PRIMARY KEY,
  visitor_code         TEXT NOT NULL UNIQUE,            -- e.g. VIS-8F3K2Q (public-facing ID)
  request_id           TEXT UNIQUE REFERENCES visitor_access_requests(id) ON DELETE SET NULL,
  full_name            TEXT NOT NULL,
  email                TEXT NOT NULL,
  mobile               TEXT NOT NULL,
  company              TEXT NOT NULL,
  designation          TEXT NOT NULL,
  purpose              TEXT NOT NULL,
  linkedin_url         TEXT,
  website_url          TEXT,
  password_hash        TEXT,                            -- NULL until activation; bcrypt/argon2 only
  status               TEXT NOT NULL DEFAULT 'pending_activation'
                       CHECK (status IN ('pending_activation','active','disabled')),
  expires_at           TIMESTAMPTZ NOT NULL,            -- default now()+30d, admin-editable
  activated_at         TIMESTAMPTZ,
  disabled_at          TIMESTAMPTZ,
  disabled_reason      TEXT,
  last_login_at        TIMESTAMPTZ,
  total_online_seconds BIGINT NOT NULL DEFAULT 0,
  failed_login_count   INTEGER NOT NULL DEFAULT 0,
  locked_until         TIMESTAMPTZ,
  expiry_reminder_sent_at TIMESTAMPTZ,
  created_by           TEXT,
  created_at           TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at           TIMESTAMPTZ NOT NULL DEFAULT now()
);
-- "expired" is derived (expires_at < now()), never stored, so it can't go stale.
CREATE UNIQUE INDEX IF NOT EXISTS uq_visitors_email ON visitors (lower(email));
CREATE INDEX IF NOT EXISTS idx_visitors_status_exp  ON visitors (status, expires_at);

-- 3. Auth sessions (NOT the analytics table visitor_sessions) ----------------
CREATE TABLE IF NOT EXISTS visitor_sessions_auth (
  id               TEXT PRIMARY KEY,
  visitor_id       TEXT NOT NULL REFERENCES visitors(id) ON DELETE CASCADE,
  token_hash       TEXT NOT NULL UNIQUE,                -- SHA-256 of cookie token; raw token never stored
  login_at         TIMESTAMPTZ NOT NULL DEFAULT now(),
  last_active_at   TIMESTAMPTZ NOT NULL DEFAULT now(),  -- updated by heartbeat
  logout_at        TIMESTAMPTZ,
  expires_at       TIMESTAMPTZ NOT NULL,                -- idle/absolute expiry
  revoked_at       TIMESTAMPTZ,
  revoked_reason   TEXT,
  online_seconds   INTEGER NOT NULL DEFAULT 0,
  device_category  TEXT CHECK (device_category IN ('mobile','tablet','desktop')),
  browser          TEXT,
  os               TEXT,
  ip_address       TEXT,
  ip_anonymized_at TIMESTAMPTZ,
  created_at       TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_vsa_visitor        ON visitor_sessions_auth (visitor_id, login_at DESC);
CREATE INDEX IF NOT EXISTS idx_vsa_active         ON visitor_sessions_auth (last_active_at) WHERE logout_at IS NULL AND revoked_at IS NULL;

-- 4. One-time tokens (activation / password reset) ---------------------------
CREATE TABLE IF NOT EXISTS visitor_auth_tokens (
  id          TEXT PRIMARY KEY,
  visitor_id  TEXT NOT NULL REFERENCES visitors(id) ON DELETE CASCADE,
  type        TEXT NOT NULL CHECK (type IN ('activation','password_reset')),
  token_hash  TEXT NOT NULL UNIQUE,                     -- only the hash is stored
  expires_at  TIMESTAMPTZ NOT NULL,
  used_at     TIMESTAMPTZ,                              -- set atomically on use => one-time
  created_by  TEXT,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_vat_visitor ON visitor_auth_tokens (visitor_id, type);

-- 5. Audit log ---------------------------------------------------------------
CREATE TABLE IF NOT EXISTS visitor_audit_logs (
  id               TEXT PRIMARY KEY,
  visitor_id       TEXT REFERENCES visitors(id) ON DELETE SET NULL,
  request_id       TEXT REFERENCES visitor_access_requests(id) ON DELETE SET NULL,
  event_type       TEXT NOT NULL,   -- request_submitted, account_approved, account_rejected, account_activated,
                                    -- login_success, login_failed, logout, account_disabled, account_enabled,
                                    -- password_reset, session_revoked, expiry_extended, demo_chat_created ...
  actor_type       TEXT NOT NULL CHECK (actor_type IN ('visitor','admin','system')),
  actor_id         TEXT,
  ip_address       TEXT,
  ip_anonymized_at TIMESTAMPTZ,
  user_agent       TEXT,
  metadata         JSONB NOT NULL DEFAULT '{}'::jsonb,  -- never passwords/tokens
  created_at       TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_val_visitor_created ON visitor_audit_logs (visitor_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_val_event_created   ON visitor_audit_logs (event_type, created_at DESC);

-- 6. Email delivery log ------------------------------------------------------
CREATE TABLE IF NOT EXISTS visitor_email_logs (
  id                TEXT PRIMARY KEY,
  visitor_id        TEXT REFERENCES visitors(id) ON DELETE SET NULL,
  sender_type       TEXT NOT NULL CHECK (sender_type IN ('approval','notifications')),
  from_address      TEXT NOT NULL,
  to_email          TEXT NOT NULL,
  notification_type TEXT NOT NULL,   -- approval, activation, password_reset, expiry_reminder, disabled, expiry_extended, security_alert ...
  status            TEXT NOT NULL DEFAULT 'queued' CHECK (status IN ('queued','sent','failed')),
  provider_message_id TEXT,
  error_message     TEXT,            -- sanitized, never contains credentials/links with tokens
  created_at        TIMESTAMPTZ NOT NULL DEFAULT now(),
  sent_at           TIMESTAMPTZ
);
CREATE INDEX IF NOT EXISTS idx_vel_visitor ON visitor_email_logs (visitor_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_vel_status  ON visitor_email_logs (status, created_at DESC);

-- 7. Demo chat (fully separate from live_chats / live_chat_messages) ---------
CREATE TABLE IF NOT EXISTS demo_chats (
  id          TEXT PRIMARY KEY,
  visitor_id  TEXT NOT NULL REFERENCES visitors(id) ON DELETE CASCADE,
  title       TEXT NOT NULL DEFAULT 'Demo Chat',
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_dc_visitor ON demo_chats (visitor_id, updated_at DESC);

CREATE TABLE IF NOT EXISTS demo_chat_messages (
  id          TEXT PRIMARY KEY,
  chat_id     TEXT NOT NULL REFERENCES demo_chats(id) ON DELETE CASCADE,
  visitor_id  TEXT NOT NULL REFERENCES visitors(id) ON DELETE CASCADE, -- denormalized: every query filters on it (IDOR guard)
  role        TEXT NOT NULL CHECK (role IN ('user','assistant')),
  content     TEXT NOT NULL,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_dcm_chat    ON demo_chat_messages (chat_id, created_at);
CREATE INDEX IF NOT EXISTS idx_dcm_visitor ON demo_chat_messages (visitor_id, created_at DESC);

COMMIT;

-- ROLLBACK (manual, only if you ever need it; touches only the 8 new tables):
-- DROP TABLE IF EXISTS demo_chat_messages, demo_chats, visitor_email_logs, visitor_audit_logs,
--   visitor_auth_tokens, visitor_sessions_auth, visitors, visitor_access_requests;
